-- Add operator-editable discovery without changing existing persona or checkout policies.
INSERT INTO public.agent_configuration_catalog(key, definition)
SELECT item->>'key', item FROM jsonb_array_elements($catalog$[{"key": "contextualDiscoveryEnabled", "target": "policy", "attribute": "contextualDiscoveryEnabled", "default": false, "label": "Ativar qualificação contextual", "type": "boolean", "description": "Perguntas por assunto em buscas abertas. Preserva modelos específicos, variantes e checkout.", "group": "Qualificação contextual", "readOnly": false}, {"key": "contextualDiscoveryRules", "target": "policy", "attribute": "contextualDiscoveryRules", "default": "{\n  \"maxQuestions\": 3,\n  \"readyGroups\": [\n    [\n      \"brand\",\n      \"budget\"\n    ],\n    [\n      \"brand\",\n      \"style\",\n      \"case_size\"\n    ],\n    [\n      \"brand\",\n      \"occasion\",\n      \"case_size\"\n    ],\n    [\n      \"budget\",\n      \"attributes\"\n    ]\n  ],\n  \"directRequestPattern\": \"\\\\b(?:mostre|mande|envie)\\\\s+(?:as\\\\s+)?(?:opções|opcoes|modelos|lista)|\\\\b(?:pode buscar|pode pesquisar|sem perguntas|não quero responder|nao quero responder)\\\\b\",\n  \"questions\": [\n    {\n      \"slot\": \"model_intent\",\n      \"instruction\": \"Descubra se já tem um modelo em mente ou deseja uma indicação. Não repita a marca como pergunta.\",\n      \"fallback\": \"Você já tem algum modelo em mente ou gostaria de uma sugestão?\"\n    },\n    {\n      \"slot\": \"budget\",\n      \"instruction\": \"Pergunte cordialmente a faixa de investimento, sem pressionar.\",\n      \"fallback\": \"Qual faixa de investimento você tem em mente?\"\n    },\n    {\n      \"slot\": \"occasion\",\n      \"instruction\": \"Descubra o uso ou ocasião, usando termos simples, como dia a dia, trabalho ou esporte.\",\n      \"fallback\": \"Você procura um relógio para o dia a dia, trabalho ou alguma ocasião especial?\"\n    },\n    {\n      \"slot\": \"case_size\",\n      \"instruction\": \"Pergunte preferência de tamanho. Aceite pequeno ou grande e não exija medida do pulso. Não converta gosto subjetivo em milímetros exatos.\",\n      \"fallback\": \"Você prefere um relógio menor e discreto ou uma caixa maior?\"\n    },\n    {\n      \"slot\": \"color\",\n      \"instruction\": \"Descubra a preferência de cor do mostrador se isso ajudar a escolher.\",\n      \"fallback\": \"Tem alguma preferência de cor para o mostrador?\"\n    },\n    {\n      \"slot\": \"strap\",\n      \"instruction\": \"Descubra a preferência de pulseira, diferenciando-a do material da caixa.\",\n      \"fallback\": \"Você prefere pulseira de metal, couro ou borracha?\"\n    }\n  ],\n  \"detailLimit\": 3\n}", "label": "Assuntos e regras de qualificação", "type": "textarea", "description": "JSON editável: questions define prioridade, instrução e contingência; readyGroups define combinações suficientes; maxQuestions limita perguntas; directRequestPattern libera pedidos diretos. detailLimit limita a confirmação de fichas incompletas por consulta (0 a 6).", "group": "Qualificação contextual", "readOnly": false, "maxLength": 16000}, {"key": "message.contextual_discovery_instruction", "target": "message", "attribute": "contextual_discovery_instruction", "default": "Faça somente uma pergunta breve e cordial sobre o slot em question_to_ask, seguindo sua instruction. Use a persona para redigir naturalmente; fallback é apenas exemplo e contingência. Não acrescente outra pergunta ou outro assunto. Considere as preferências já informadas. Não use asteriscos, links, preços ou sugestões de produtos nesta etapa. Não exija medida do pulso. Uma resposta não sei deve avançar para outro assunto, sem repetir a pergunta. Características são preferências do cliente, nunca fatos confirmados do catálogo.", "label": "Instrução de perguntas naturais", "description": "Orientação enviada à OpenAI para formular a pergunta escolhida.", "group": "Qualificação contextual", "type": "textarea", "maxLength": 5000, "readOnly": false}]$catalog$::jsonb) AS item
ON CONFLICT (key) DO UPDATE SET definition=EXCLUDED.definition, updated_at=now();

DO $$
DECLARE agent public.workspace_agents%ROWTYPE;
BEGIN
 FOR agent IN SELECT * FROM public.workspace_agents
 WHERE agent_type='nsagent' AND status='active' AND config_version > 0
 LOOP
  IF NOT coalesce(agent.configuration->'runtime'->'values', '{}'::jsonb) ? 'contextualDiscoveryEnabled' THEN
   PERFORM public.publish_workspace_agent_config(agent.workspace_id,
    agent.configuration || jsonb_build_object('runtime',
     coalesce(agent.configuration->'runtime','{}'::jsonb) || jsonb_build_object('schemaVersion',2,'values',
      coalesce(agent.configuration->'runtime'->'values','{}'::jsonb) || jsonb_build_object('contextualDiscoveryEnabled',true))),
    'migration:contextual-discovery',agent.config_version);
  END IF;
 END LOOP;
END $$;
